const queueThreshold = parseInt($env.QUEUE_ALERT_THRESHOLD || '50', 10);
const diskAlertPct = parseInt($env.DISK_ALERT_PCT || '80', 10);
const diskTotalGB = 119;
return [{ json: { queueThreshold, diskAlertPct, diskTotalGB, ts: new Date().toISOString() } }];

/**
 * MED-09 FIX: Removed execSync('df -k /') shell execution.
 * Disk usage is handled externally via Docker/Prometheus.
 */
var cfg = $('B0 - Config').first().json;
var pgRow = $input.first().json;

var pendingCount = parseInt(pgRow.pending_count || '0', 10);
var runningCount = parseInt(pgRow.running_count || '0', 10);
var errorsLastHour = parseInt(pgRow.errors_last_hour || '0', 10);
var totalLastHour = parseInt(pgRow.total_last_hour || '0', 10);
var errorRate = totalLastHour > 0 ? (errorsLastHour / totalLastHour) : 0;

// MED-09: Disk metrics now handled by external monitoring (no shell exec)
var diskUsedGB = -1;
var diskUsedPct = -1;

var ts = new Date().toISOString();

console.log(JSON.stringify({
  level: 'INFO',
  event: 'QUEUE_DEPTH_METRIC',
  pending_count: pendingCount,
  running_count: runningCount,
  errors_last_hour: errorsLastHour,
  error_rate_1h: Math.round(errorRate * 1000) / 1000,
  ts: ts
}));

var alerts = [];
var queueAbove = pendingCount > cfg.queueThreshold;

return [{ json: {
  pendingCount: pendingCount,
  runningCount: runningCount,
  errorsLastHour: errorsLastHour,
  errorRate: errorRate,
  diskUsedGB: diskUsedGB,
  diskUsedPct: diskUsedPct,
  queueAbove: queueAbove,
  queueThreshold: cfg.queueThreshold,
  diskAlertPct: cfg.diskAlertPct,
  alerts: alerts,
  ts: ts
}}];

var metrics = $('B0 - Compute Metrics').first().json;
var redisVal = $input.first().json;
var currentCount = parseInt(redisVal?.value || redisVal || '0', 10) || 0;

var newCount = metrics.queueAbove ? currentCount + 1 : 0;

var queueAlert = null;
if (metrics.queueAbove && newCount >= 2) {
  queueAlert = {
    level: 'CRITICAL',
    event: 'QUEUE_DEPTH_ALERT',
    message: 'Queue depth ' + metrics.pendingCount + ' exceeds threshold ' + metrics.queueThreshold + ' for ' + newCount + ' consecutive 5-min windows',
    pending_count: metrics.pendingCount,
    threshold: metrics.queueThreshold,
    consecutive_windows: newCount,
    ts: metrics.ts
  };
  console.log(JSON.stringify(queueAlert));
}

return [{ json: {
  pendingCount: metrics.pendingCount,
  runningCount: metrics.runningCount,
  errorsLastHour: metrics.errorsLastHour,
  errorRate: metrics.errorRate,
  diskUsedGB: metrics.diskUsedGB,
  diskUsedPct: metrics.diskUsedPct,
  queueAbove: metrics.queueAbove,
  queueThreshold: metrics.queueThreshold,
  diskAlertPct: metrics.diskAlertPct,
  alerts: metrics.alerts,
  ts: metrics.ts,
  newCount: newCount,
  queueAlert: queueAlert
}}];
